<script>(() => {
  const intro = document.getElementById('intro');
  if (intro) {
    if (window.location.hash) intro.remove();
    else {
      intro.classList.add('show');
      if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) intro.classList.add('reduced');
