    }
  }
  // Nach dem Entfernen des Intros muss ein direkter Sprunganker neu ausgerichtet
  // werden, sonst landet der Zielbereich auf der Seite zu weit oben.
  const alignHashTarget = () => {
    const rawHash = window.location.hash.slice(1);
    if (!rawHash) return;
    let id = rawHash;
    try { id = decodeURIComponent(rawHash); } catch (_) { return; }
    const target = document.getElementById(id);
    if (!target) return;
    // Die Navigation scrollt nicht als sichtbare Leiste mit. Deshalb darf
    // beim Ziel kein pauschaler Header-Abstand abgezogen werden.
    const top = Math.max(0, target.getBoundingClientRect().top + window.scrollY);
    const previousBehavior = document.documentElement.style.scrollBehavior;
    document.documentElement.style.scrollBehavior = 'auto';
    window.scrollTo(0, top);
    document.documentElement.style.scrollBehavior = previousBehavior;
  };
  const alignHashSoon = () => window.requestAnimationFrame(() => window.setTimeout(alignHashTarget, 80));
  if (window.location.hash) alignHashSoon();
  window.addEventListener('hashchange', alignHashSoon);
  window.addEventListener('load', () => { if (window.location.hash) alignHashSoon(); }, {once:true});
  document.querySelectorAll('a[href^="#"]').forEach(link => link.addEventListener('click', event => {
    const href = link.getAttribute('href') || '';
    const id = href.slice(1);
    if (!id || !document.getElementById(id)) return;
    event.preventDefault();
    history.pushState(null, '', href);
    alignHashSoon();
  }));
