          <span>03</span>
          <h3>Business &amp; Möglichkeiten</h3>
          <p>Werde sichtbar, lerne Marken kennen und entwickle Kooperationen und Angebote für die Branche.</p>
          <a href="#moeglichkeiten">Möglichkeiten sehen ↗</a>
        </article>
      </div>`;
    offers.parentNode.insertBefore(pillars, offers);
    const oldEyebrow = offers.querySelector('.eyebrow');
    const oldHeading = offers.querySelector('h2');
    if (oldEyebrow) oldEyebrow.textContent = 'Die Bereiche dahinter';
    if (oldHeading) oldHeading.textContent = 'Ein Netzwerk. Viele Möglichkeiten.';
  }

})();
</script>
</body>
</html>
